const FOUR_PANEL_EMPTY_SNAPSHOT = "__EMPTY__";

function mahjongTileLabel(id: number): string {
  if (!Number.isInteger(id) || id < 0) return "?";
  return MAHJONG_TILE_LABELS[id % MAHJONG_TILE_LABELS.length] || "?";
}

function shuffleNumberList(list: number[]): number[] {
  const next = [...list];
  for (let i = next.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [next[i], next[j]] = [next[j], next[i]];
  }
  return next;
}

function sortMahjongTiles(tiles: number[]): number[] {
  return [...tiles].sort((a, b) => a - b);
}

function normalizeMahjongTileValue(value: unknown): MahjongCell | null {
  if (typeof value === "number" && Number.isInteger(value) && value >= 0 && value < MAHJONG_TYPE_COUNT) {
    return value;
  }
  if (typeof value !== "string") return null;

  const key = value.trim().toLowerCase();
  if (!key) return null;
  if (Object.prototype.hasOwnProperty.call(MAHJONG_TILE_CODE_TO_ID, key)) {
    return MAHJONG_TILE_CODE_TO_ID[key];
  }

  const asNumber = Number.parseInt(key, 10);
  if (Number.isInteger(asNumber) && asNumber >= 0 && asNumber < MAHJONG_TYPE_COUNT) {
    return asNumber;
  }

  return null;
}

function normalizeMahjongTileList(source: unknown): number[] {
  if (!Array.isArray(source)) return [];
  return source
    .flat(Infinity)
    .map((value) => normalizeMahjongTileValue(value))
    .filter((value): value is number => value !== null);
}

function normalizeMahjongTileInstanceList(source: unknown): MahjongTileInstance[] {
  if (!Array.isArray(source)) return [];
  const out: MahjongTileInstance[] = [];
  source.forEach((item) => {
    if (typeof item === "number" || typeof item === "string") {
      const tile = normalizeMahjongTileValue(item);
      if (tile !== null) out.push(createMahjongTileInstance(tile));
      return;
    }
    if (item && typeof item === "object") {
      const raw = item as { tile?: unknown; instanceId?: unknown };
      const tile = normalizeMahjongTileValue(raw.tile);
      if (tile === null) return;
      const providedId = typeof raw.instanceId === "string" && raw.instanceId.trim().length > 0
        ? raw.instanceId.trim()
        : createMahjongTileInstance(tile).instanceId;
      out.push({ instanceId: providedId, tile });
    }
  });
  return out;
}

function createMahjongWall(config: { removedTiles: MahjongCell[] } = MAHJONG_RULE_CONFIG_BASE.yonma): number[] {
  const removed = new Set(config.removedTiles);
  const wall: number[] = [];
  for (let tile = 0; tile < MAHJONG_TYPE_COUNT; tile += 1) {
    if (removed.has(tile)) continue;
    for (let copy = 0; copy < 4; copy += 1) {
      wall.push(tile);
    }
  }
  return shuffleNumberList(wall);
}

function createMahjongStartBoard(config: { playerCount: number; removedTiles: MahjongCell[] } = MAHJONG_RULE_CONFIG_BASE.yonma): { hand: MahjongCell[]; wall: MahjongCell[] } {
  const wall = createMahjongWall(config);
  const reserveForOpponents = Math.max(0, Math.floor(config.playerCount - 1)) * MAHJONG_START_HAND_COUNT;
  const hand = sortMahjongTiles(wall.slice(0, MAHJONG_START_HAND_COUNT));
  return {
    hand,
    wall: wall.slice(MAHJONG_START_HAND_COUNT + reserveForOpponents),
  };
}

function mahjongRemainingCount(wall: MahjongCell[]): number {
  return wall.length;
}

function summarizeMahjongRuleWall(config: { playerCount: number; removedTiles: MahjongCell[] }): {
  totalTiles: number;
  excludedTiles: MahjongCell[];
  tileCounts: Record<string, number>;
  playersDealtTiles: number;
} {
  const excludedSet = new Set(config.removedTiles);
  const excludedTiles = [...excludedSet].sort((a, b) => a - b);
  const tileCounts: Record<string, number> = {};
  let totalTiles = 0;

  for (let tile = 0; tile < MAHJONG_TYPE_COUNT; tile += 1) {
    const count = excludedSet.has(tile) ? 0 : 4;
    tileCounts[mahjongTileLabel(tile)] = count;
    totalTiles += count;
  }

  const playersDealtTiles = Math.max(0, Math.floor(config.playerCount)) * MAHJONG_START_HAND_COUNT;

  return {
    totalTiles,
    excludedTiles,
    tileCounts,
    playersDealtTiles,
  };
}

function mahjongCountTiles(tiles: MahjongCell[]): number[] {
  const counts = Array.from({ length: MAHJONG_TYPE_COUNT }, () => 0);
  tiles.forEach((tile) => {
    counts[tile] += 1;
  });
  return counts;
}

function mahjongCanFormMelds(counts: number[]): boolean {
  let first = -1;
  for (let i = 0; i < counts.length; i += 1) {
    if (counts[i] > 0) {
      first = i;
      break;
    }
  }
  if (first < 0) return true;

  if (counts[first] >= 3) {
    counts[first] -= 3;
    if (mahjongCanFormMelds(counts)) {
      counts[first] += 3;
      return true;
    }
    counts[first] += 3;
  }

  const suit = Math.floor(first / 9);
  const rank = first % 9;
  const canChow = suit <= 2 && rank <= 6 && counts[first + 1] > 0 && counts[first + 2] > 0;
  if (canChow) {
    counts[first] -= 1;
    counts[first + 1] -= 1;
    counts[first + 2] -= 1;
    if (mahjongCanFormMelds(counts)) {
      counts[first] += 1;
      counts[first + 1] += 1;
      counts[first + 2] += 1;
      return true;
    }
    counts[first] += 1;
    counts[first + 1] += 1;
    counts[first + 2] += 1;
  }

  return false;
}

function mahjongIsStandardWin(hand: MahjongCell[]): boolean {
  if (hand.length !== 14) return false;
  const counts = mahjongCountTiles(hand);
  for (let pairTile = 0; pairTile < counts.length; pairTile += 1) {
    if (counts[pairTile] < 2) continue;
    counts[pairTile] -= 2;
    if (mahjongCanFormMelds(counts)) {
      counts[pairTile] += 2;
      return true;
    }
    counts[pairTile] += 2;
  }
  return false;
}

function mahjongIsSevenPairs(hand: MahjongCell[]): boolean {
  if (hand.length !== 14) return false;
  const counts = mahjongCountTiles(hand);
  let pairUnits = 0;
  for (let i = 0; i < counts.length; i += 1) {
    const count = counts[i];
    if (count % 2 !== 0) return false;
    pairUnits += count / 2;
  }
  return pairUnits === 7;
}

function mahjongIsThirteenOrphans(hand: MahjongCell[]): boolean {
  if (hand.length !== 14) return false;
  const counts = mahjongCountTiles(hand);
  let pairFound = false;

  for (let tile = 0; tile < MAHJONG_TYPE_COUNT; tile += 1) {
    const isOrphan = MAHJONG_ORPHAN_TILE_IDS.includes(tile as (typeof MAHJONG_ORPHAN_TILE_IDS)[number]);
    if (!isOrphan && counts[tile] > 0) return false;
  }

  for (const tile of MAHJONG_ORPHAN_TILE_IDS) {
    if (counts[tile] === 0) return false;
    if (counts[tile] >= 2) {
      if (pairFound) return false;
      pairFound = true;
    }
  }

  return pairFound;
}

function mahjongIsWinningHand(hand: MahjongCell[]): boolean {
  return mahjongIsStandardWin(hand) || mahjongIsSevenPairs(hand) || mahjongIsThirteenOrphans(hand);
}

function mahjongFindWinningTiles(hand: MahjongCell[]): MahjongCell[] {
  if (hand.length !== 13) return [];
  const counts = mahjongCountTiles(hand);
  const waits: MahjongCell[] = [];
  for (let tile = 0; tile < MAHJONG_TYPE_COUNT; tile += 1) {
    if (counts[tile] >= 4) continue;
    if (mahjongIsWinningHand([...hand, tile])) waits.push(tile);
  }
  return waits;
}

function mahjongFindBestDiscards(hand: MahjongCell[]): Array<{ index: number; tile: MahjongCell; waits: MahjongCell[]; outs: number }> {
  if (hand.length !== 14) return [];

  const results: Array<{ index: number; tile: MahjongCell; waits: MahjongCell[]; outs: number }> = [];
  const seenTile = new Set<number>();

  for (let index = 0; index < hand.length; index += 1) {
    const tile = hand[index];
    if (seenTile.has(tile)) continue;
    seenTile.add(tile);

    const nextHand = hand.filter((_, i) => i !== index);
    const waits = mahjongFindWinningTiles(nextHand);
    const nextCounts = mahjongCountTiles(nextHand);
    const outs = waits.reduce((sum, waitTile) => sum + Math.max(0, 4 - nextCounts[waitTile]), 0);
    results.push({ index, tile, waits, outs });
  }

  return results.sort((a, b) => {
    if (b.outs !== a.outs) return b.outs - a.outs;
    if (b.waits.length !== a.waits.length) return b.waits.length - a.waits.length;
    return a.tile - b.tile;
  });
}

function mahjongFindRiichiDiscardIndexes(hand: MahjongCell[]): number[] {
  if (hand.length !== 14) return [];
  return mahjongFindBestDiscards(hand)
    .filter((item) => item.waits.length > 0)
    .map((item) => item.index);
}

function mahjongConcealedCountAfterDiscard(meldCount: number): number {
  return 13 - Math.max(0, meldCount) * 3;
}

function mahjongConcealedCountAfterDraw(meldCount: number): number {
  return mahjongConcealedCountAfterDiscard(meldCount) + 1;
}

let mahjongTileInstanceSeq = 0;

function createMahjongTileInstance(tile: MahjongCell): MahjongTileInstance {
  mahjongTileInstanceSeq += 1;
  return {
    instanceId: `mj-${mahjongTileInstanceSeq}`,
    tile,
  };
}

function mapMahjongTilesToInstances(tiles: MahjongCell[]): MahjongTileInstance[] {
  return tiles.map((tile) => createMahjongTileInstance(tile));
}

function mahjongTileNumbersFromInstances(tiles: MahjongTileInstance[]): MahjongCell[] {
  return tiles.map((item) => item.tile);
}

function sortMahjongTileInstances(tiles: MahjongTileInstance[]): MahjongTileInstance[] {
  return [...tiles].sort((a, b) => a.tile - b.tile);
}

function mahjongBuildHandTiles(concealedHand: MahjongTileInstance[], drawnTile: MahjongTileInstance | null): MahjongCell[] {
  return drawnTile ? [...mahjongTileNumbersFromInstances(concealedHand), drawnTile.tile] : mahjongTileNumbersFromInstances(concealedHand);
}

function normalizeMahjongHandState(
  concealedHand: MahjongTileInstance[],
  drawnTile: MahjongTileInstance | null,
  meldCount: number,
): {
  concealedHand: MahjongTileInstance[];
  drawnTile: MahjongTileInstance | null;
} {
  if (drawnTile) {
    return {
      concealedHand: [...concealedHand],
      drawnTile,
    };
  }

  const expectedAfterDraw = mahjongConcealedCountAfterDraw(meldCount);
  if (concealedHand.length === expectedAfterDraw && concealedHand.length > 0) {
    return {
      concealedHand: concealedHand.slice(0, -1),
      drawnTile: concealedHand[concealedHand.length - 1] ?? null,
    };
  }

  return {
    concealedHand: [...concealedHand],
    drawnTile: null,
  };
}

function mahjongRemoveTilesOnce(hand: MahjongCell[], targets: MahjongCell[]): MahjongCell[] | null {
  const next = [...hand];
  for (const tile of targets) {
    const index = next.indexOf(tile);
    if (index < 0) return null;
    next.splice(index, 1);
  }
  return next;
}

function mahjongFindKakanCandidates(hand: MahjongCell[], melds: MahjongMeldView[]): MahjongCell[] {
  if (hand.length <= 0 || melds.length <= 0) return [];
  const counts = mahjongCountTiles(hand);
  const seen = new Set<MahjongCell>();
  const candidates: MahjongCell[] = [];
  melds.forEach((meld) => {
    if (meld.type !== "pon") return;
    const base = meld.tiles[0];
    if (typeof base !== "number") return;
    if (seen.has(base)) return;
    seen.add(base);
    if ((counts[base] || 0) > 0) {
      candidates.push(base);
    }
  });
  return candidates;
}

function mahjongCanPon(hand: MahjongCell[], discard: MahjongCell | null): boolean {
  if (discard === null) return false;
  const count = hand.reduce((sum, tile) => sum + (tile === discard ? 1 : 0), 0);
  return count >= 2;
}

function mahjongCanMinkan(hand: MahjongCell[], discard: MahjongCell | null): boolean {
  if (discard === null) return false;
  const count = hand.reduce((sum, tile) => sum + (tile === discard ? 1 : 0), 0);
  return count >= 3;
}

function mahjongFindChiCandidates(hand: MahjongCell[], discard: MahjongCell | null): MahjongCell[][] {
  if (discard === null) return [];
  if (discard >= 27) return [];

  const suitBase = Math.floor(discard / 9) * 9;
  const rank = discard % 9;
  const candidates: MahjongCell[][] = [];
  const count = mahjongCountTiles(hand);

  const patterns: Array<[number, number]> = [
    [rank - 2, rank - 1],
    [rank - 1, rank + 1],
    [rank + 1, rank + 2],
  ];

  patterns.forEach(([a, b]) => {
    if (a < 0 || b > 8) return;
    const t1 = (suitBase + a) as MahjongCell;
    const t2 = (suitBase + b) as MahjongCell;
    if ((count[t1] || 0) > 0 && (count[t2] || 0) > 0) {
      candidates.push([t1, discard, t2].sort((x, y) => x - y) as MahjongCell[]);
    }
  });

  return candidates;
}

function mahjongFindAnkanCandidates(hand: MahjongCell[]): MahjongCell[] {
  const count = mahjongCountTiles(hand);
  const candidates: MahjongCell[] = [];
  for (let tile = 0; tile < MAHJONG_TYPE_COUNT; tile += 1) {
    if (count[tile] >= 4) candidates.push(tile as MahjongCell);
  }
  return candidates;
}

function mahjongCanAbortiveDraw(hand: MahjongCell[], river: MahjongCell[]): boolean {
  if (hand.length !== 14) return false;
  if (river.length > 0) return false;
  const unique = new Set(hand.filter((tile) => mahjongIsTerminalOrHonor(tile)));
  return unique.size >= 9;
}

function mahjongIsHonor(tile: MahjongCell): boolean {
  return tile >= 27;
}

function mahjongIsTerminal(tile: MahjongCell): boolean {
  if (mahjongIsHonor(tile)) return false;
  const rank = (tile % 9) + 1;
  return rank === 1 || rank === 9;
}

function mahjongIsTerminalOrHonor(tile: MahjongCell): boolean {
  return mahjongIsHonor(tile) || mahjongIsTerminal(tile);
}

function mahjongTileSuit(tile: MahjongCell): "m" | "p" | "s" | "z" {
  if (tile <= 8) return "m";
  if (tile <= 17) return "p";
  if (tile <= 26) return "s";
  return "z";
}

function mahjongExtractPattern(
  hand: MahjongCell[],
  meldTarget: number,
): { pairTile: MahjongCell; melds: MahjongMeld[] } | null {
  if (meldTarget < 0) return null;
  if (hand.length !== meldTarget * 3 + 2) return null;
  const counts = mahjongCountTiles(hand);

  const recurse = (work: number[], melds: MahjongMeld[]): MahjongMeld[] | null => {
    if (melds.length > meldTarget) return null;
    let first = -1;
    for (let i = 0; i < work.length; i += 1) {
      if (work[i] > 0) {
        first = i;
        break;
      }
    }
    if (first < 0) {
      return melds.length === meldTarget ? melds : null;
    }

    if (work[first] >= 3) {
      work[first] -= 3;
      const tripletResult = recurse(work, [...melds, { type: "triplet", tile: first }]);
      work[first] += 3;
      if (tripletResult) return tripletResult;
    }

    const suit = Math.floor(first / 9);
    const rank = first % 9;
    if (suit <= 2 && rank <= 6 && work[first + 1] > 0 && work[first + 2] > 0) {
      work[first] -= 1;
      work[first + 1] -= 1;
      work[first + 2] -= 1;
      const sequenceResult = recurse(work, [...melds, { type: "sequence", tile: first }]);
      work[first] += 1;
      work[first + 1] += 1;
      work[first + 2] += 1;
      if (sequenceResult) return sequenceResult;
    }

    return null;
  };

  for (let pairTile = 0; pairTile < counts.length; pairTile += 1) {
    if (counts[pairTile] < 2) continue;
    counts[pairTile] -= 2;
    const melds = recurse(counts, []);
    counts[pairTile] += 2;
    if (melds && melds.length === meldTarget) {
      return { pairTile, melds };
    }
  }

  return null;
}

function mahjongExtractStandardPattern(hand: MahjongCell[]): { pairTile: MahjongCell; melds: MahjongMeld[] } | null {
  return mahjongExtractPattern(hand, 4);
}

function mahjongEstimatePoint(han: number, fu: number, isYakuman: boolean): number {
  if (isYakuman) return 32000;
  if (han <= 0) return 0;

  const mangan = han >= 5 || (han === 4 && fu >= 40) || (han === 3 && fu >= 70);
  let basePoint: number;
  if (han >= 13) basePoint = 8000;
  else if (han >= 11) basePoint = 6000;
  else if (han >= 8) basePoint = 4000;
  else if (han >= 6) basePoint = 3000;
  else if (mangan) basePoint = 2000;
  else basePoint = fu * (2 ** (han + 2));

  return Math.ceil((basePoint * 4) / 100) * 100;
}

function mahjongIsSelfFuriten(baseHand13: MahjongCell[], river: MahjongCell[]): boolean {
  if (baseHand13.length !== 13) return false;
  if (river.length <= 0) return false;
  const waits = new Set(mahjongFindWinningTiles(baseHand13));
  return river.some((tile) => waits.has(tile));
}

function mahjongSummarizeWin(
  hand: MahjongCell[],
  context: {
    winType: "tsumo" | "ron";
    winningTile: MahjongCell;
    isRiichi: boolean;
    meldCount?: number;
    isMenzen?: boolean;
  },
): MahjongWinSummary | null {
  const meldCount = Math.max(0, Math.floor(context.meldCount ?? 0));
  const closedMeldTarget = 4 - meldCount;
  if (closedMeldTarget < 0) return null;
  if (hand.length !== closedMeldTarget * 3 + 2) return null;

  const isMenzen = context.isMenzen !== false;
  const yakuKeys: Array<keyof typeof LOGIN_I18N.ja> = [];
  let han = 0;

  if (context.isRiichi) {
    han += 1;
    yakuKeys.push("mahjongRiichi");
  }

  if (context.winType === "tsumo" && isMenzen) {
    han += 1;
    yakuKeys.push("mahjongYakuMenzenTsumo");
  }

  if (meldCount === 0 && mahjongIsThirteenOrphans(hand)) {
    yakuKeys.push("mahjongYakuKokushi");
    return {
      winType: context.winType,
      winningTile: context.winningTile,
      yakuKeys,
      han: 13,
      fu: 0,
      point: mahjongEstimatePoint(13, 0, true),
      isYakuman: true,
    };
  }

  if (meldCount === 0 && mahjongIsSevenPairs(hand)) {
    han += 2;
    yakuKeys.push("mahjongYakuChiitoitsu");

    const hasHonor = hand.some((tile) => mahjongIsHonor(tile));
    const suitSet = new Set(hand.filter((tile) => !mahjongIsHonor(tile)).map((tile) => mahjongTileSuit(tile)));
    if (!hasHonor && suitSet.size === 1) {
      han += 6;
      yakuKeys.push("mahjongYakuChinitsu");
    } else if (hasHonor && suitSet.size === 1) {
      han += 3;
      yakuKeys.push("mahjongYakuHonitsu");
    }

    return {
      winType: context.winType,
      winningTile: context.winningTile,
      yakuKeys,
      han,
      fu: 25,
      point: mahjongEstimatePoint(han, 25, false),
      isYakuman: false,
    };
  }

  const pattern = mahjongExtractPattern(hand, closedMeldTarget);
  if (!pattern) return null;

  const allSimple = hand.every((tile) => !mahjongIsTerminalOrHonor(tile));
  if (allSimple) {
    han += 1;
    yakuKeys.push("mahjongYakuTanyao");
  }

  const allSequences = pattern.melds.length > 0 && pattern.melds.every((meld) => meld.type === "sequence");
  const pairIsValueHonor = pattern.pairTile >= 31 || pattern.pairTile === 27;
  if (allSequences && !pairIsValueHonor) {
    han += 1;
    yakuKeys.push("mahjongYakuPinfu");
  }

  const allTriplets = pattern.melds.every((meld) => meld.type === "triplet");
  if (allTriplets) {
    han += 2;
    yakuKeys.push("mahjongYakuToitoi");
  }

  const yakuhaiTripletCount = pattern.melds.filter(
    (meld) => meld.type === "triplet" && (meld.tile === 27 || (meld.tile >= 31 && meld.tile <= 33)),
  ).length;
  for (let i = 0; i < yakuhaiTripletCount; i += 1) {
    han += 1;
    yakuKeys.push("mahjongYakuYakuhai");
  }

  const hasHonor = hand.some((tile) => mahjongIsHonor(tile));
  const suitSet = new Set(hand.filter((tile) => !mahjongIsHonor(tile)).map((tile) => mahjongTileSuit(tile)));
  if (!hasHonor && suitSet.size === 1) {
    han += 6;
    yakuKeys.push("mahjongYakuChinitsu");
  } else if (hasHonor && suitSet.size === 1) {
    han += 3;
    yakuKeys.push("mahjongYakuHonitsu");
  }

  let fu = 20;
  fu += 2;
  if (pattern.pairTile >= 31 && pattern.pairTile <= 33) fu += 2;

  pattern.melds.forEach((meld) => {
    if (meld.type !== "triplet") return;
    fu += mahjongIsTerminalOrHonor(meld.tile) ? 8 : 4;
  });

  fu = Math.max(20, Math.ceil(fu / 10) * 10);

  if (han <= 0) {
    return null;
  }

  return {
    winType: context.winType,
    winningTile: context.winningTile,
    yakuKeys,
    han,
    fu,
    point: mahjongEstimatePoint(han, fu, false),
    isYakuman: false,
  };
}

function evaluateMahjongWinAction(params: {
  baseHand: MahjongCell[];
  winType: "tsumo" | "ron";
  winningTile?: MahjongCell | null;
  isRiichi: boolean;
  river: MahjongCell[];
  meldCount?: number;
  isMenzen?: boolean;
  bonusHan?: number;
}): MahjongWinEvaluation {
  const meldCount = Math.max(0, Math.floor(params.meldCount ?? 0));
  const closedMeldTarget = 4 - meldCount;
  const neededClosedTiles = 14 - meldCount * 3;
  const winningTile = params.winningTile ?? null;

  const candidateHand = params.winType === "ron"
    ? (winningTile === null ? [...params.baseHand] : [...params.baseHand, winningTile])
    : [...params.baseHand];

  const furiten = params.winType === "ron" && mahjongIsSelfFuriten(params.baseHand, params.river);

  if (candidateHand.length !== neededClosedTiles) {
    return {
      ok: false,
      reason: `tile-count-mismatch:${candidateHand.length}/${neededClosedTiles}`,
      candidateHand,
      tileCount: candidateHand.length,
      furiten,
      summary: null,
    };
  }

  if (params.winType === "ron" && winningTile === null) {
    return {
      ok: false,
      reason: "missing-ron-tile",
      candidateHand,
      tileCount: candidateHand.length,
      furiten,
      summary: null,
    };
  }

  if (furiten) {
    return {
      ok: false,
      reason: "furiten-self-river",
      candidateHand,
      tileCount: candidateHand.length,
      furiten,
      summary: null,
    };
  }

  const shapeOk = closedMeldTarget >= 0 && (
    (meldCount === 0 && mahjongIsWinningHand(candidateHand))
    || (meldCount > 0 && mahjongExtractPattern(candidateHand, closedMeldTarget) !== null)
  );

  if (!shapeOk) {
    return {
      ok: false,
      reason: "not-winning-shape",
      candidateHand,
      tileCount: candidateHand.length,
      furiten,
      summary: null,
    };
  }

  const summary = mahjongSummarizeWin(candidateHand, {
    winType: params.winType,
    winningTile: (params.winType === "tsumo" ? params.baseHand[params.baseHand.length - 1] : winningTile) ?? 0,
    isRiichi: params.isRiichi,
    meldCount,
    isMenzen: params.isMenzen,
  });

  if (!summary || summary.han <= 0) {
    return {
      ok: false,
      reason: "no-yaku",
      candidateHand,
      tileCount: candidateHand.length,
      furiten,
      summary: null,
    };
  }

  const bonusHan = Math.max(0, Math.floor(params.bonusHan ?? 0));
  const finalSummary = bonusHan > 0
    ? {
      ...summary,
      han: summary.han + bonusHan,
      point: mahjongEstimatePoint(summary.han + bonusHan, summary.fu, summary.isYakuman),
    }
    : summary;

  return {
    ok: true,
    reason: "ok",
    candidateHand,
    tileCount: candidateHand.length,
    furiten,
    summary: finalSummary,
  };
}

function createFitPuzzleSolvedTiles(): number[] {
  return [1, 2, 3, 4, 5, 6, 7, 8, 0];
}

function fitPuzzleCanMove(index: number, blankIndex: number): boolean {
  const row = Math.floor(index / FIT_PUZZLE_SIZE);
  const col = index % FIT_PUZZLE_SIZE;
  const blankRow = Math.floor(blankIndex / FIT_PUZZLE_SIZE);
  const blankCol = blankIndex % FIT_PUZZLE_SIZE;
  return Math.abs(row - blankRow) + Math.abs(col - blankCol) === 1;
}

function isFitPuzzleSolved(tiles: number[]): boolean {
  const solved = createFitPuzzleSolvedTiles();
  return solved.every((tile, index) => tiles[index] === tile);
}

function createFitPuzzleShuffledTiles(stepCount = 80): number[] {
  const tiles = createFitPuzzleSolvedTiles();
  let blankIndex = tiles.indexOf(0);

  for (let step = 0; step < stepCount; step += 1) {
    const candidates: number[] = [];
    for (let index = 0; index < tiles.length; index += 1) {
      if (fitPuzzleCanMove(index, blankIndex)) {
        candidates.push(index);
      }
    }
    const pick = candidates[Math.floor(Math.random() * candidates.length)];
    if (pick === undefined) continue;
    [tiles[pick], tiles[blankIndex]] = [tiles[blankIndex], tiles[pick]];
    blankIndex = pick;
  }

  if (isFitPuzzleSolved(tiles)) {
    [tiles[7], tiles[8]] = [tiles[8], tiles[7]];
  }

  return tiles;
}

const BOARD_SIZE = 8;
const GOMOKU_SIZE = 15;
const UNO_COLORS: Array<Exclude<UnoColor, "W">> = ["R", "G", "B", "Y"];
const UNO_PLAY_ANIMATION_DELAY_MS = 140;
let unoCardSerial = 0;

function nextUnoCardId(): string {
  unoCardSerial += 1;
  return `uno-${unoCardSerial}`;
}

function createUnoNumberCard(color: Exclude<UnoColor, "W">, value: number): UnoCard {
  return {
    id: nextUnoCardId(),
    color,
    value,
    type: "number",
    symbol: String(value),
  };
}

function normalizeUnoCard(raw: unknown): UnoCard | null {
  if (!raw || typeof raw !== "object") return null;
  const card = raw as Partial<UnoCard> & Record<string, unknown>;
  const color = card.color === "R" || card.color === "G" || card.color === "B" || card.color === "Y" || card.color === "W"
    ? card.color
    : null;
  const value = Number(card.value);
  if (!color || !Number.isFinite(value)) return null;
  const type: UnoCardType =
    card.type === "skip" || card.type === "reverse" || card.type === "draw2" || card.type === "wild" || card.type === "wildDraw4"
      ? card.type
      : "number";
  const symbol = String(card.symbol || (type === "number" ? String(Math.trunc(value)) : type)).trim() || (type === "number" ? String(Math.trunc(value)) : type);
  const id = String(card.id || "").trim() || nextUnoCardId();
  return {
    id,
    color,
    value: Math.trunc(value),
    type,
    symbol,
  };
}

function normalizeUnoCardList(raw: unknown): UnoCard[] {
  if (!Array.isArray(raw)) return [];
  const seen = new Set<string>();
  const next: UnoCard[] = [];
  raw.forEach((entry) => {
    const card = normalizeUnoCard(entry);
    if (!card) return;
    if (seen.has(card.id)) {
      card.id = nextUnoCardId();
    }
    seen.add(card.id);
    next.push(card);
  });
  return next;
}

function normalizeUnoHands(raw: unknown): UnoCard[][] {
  if (!Array.isArray(raw)) return [[], []];
  return raw.map((hand) => normalizeUnoCardList(hand));
}

function isUnoWildCard(card: UnoCard): boolean {
  return card.type === "wild" || card.type === "wildDraw4" || card.color === "W";
}

function canPlayCardOnTop(card: UnoCard, top: UnoCard): boolean {
  if (isUnoWildCard(card)) return true;
  return card.color === top.color || card.value === top.value || card.symbol === top.symbol;
}

function canIncludeInMultiPlay(card: UnoCard): boolean {
  return !isUnoWildCard(card);
}

function canChainCards(previousCard: UnoCard, nextCard: UnoCard): boolean {
  if (!canIncludeInMultiPlay(previousCard) || !canIncludeInMultiPlay(nextCard)) return false;
  if (previousCard.type !== nextCard.type) return false;
  if (previousCard.type === "number") {
    return previousCard.value === nextCard.value;
  }
  return previousCard.symbol === nextCard.symbol;
}

function validateSelectedCards(selectedCards: UnoCard[], topCard: UnoCard): UnoSelectionValidation {
  if (selectedCards.length <= 0) {
    return { isValid: false, selectedCards: [], reason: "カードを1枚以上選択してください。" };
  }

  const first = selectedCards[0];
  if (!canPlayCardOnTop(first, topCard)) {
    return {
      isValid: false,
      selectedCards,
      invalidCardId: first.id,
      reason: "1枚目が場札に対して出せません。",
    };
  }

  if (selectedCards.length > 1 && !canIncludeInMultiPlay(first)) {
    return {
      isValid: false,
      selectedCards,
      invalidCardId: first.id,
      reason: "ワイルド系カードは単体でのみ提出できます。",
    };
  }

  for (let i = 1; i < selectedCards.length; i += 1) {
    const previous = selectedCards[i - 1];
    const current = selectedCards[i];
    if (isUnoWildCard(current)) {
      return {
        isValid: false,
        selectedCards,
        invalidCardId: current.id,
        reason: "ワイルド系カードは連続提出に含められません。",
      };
    }
    if (!canChainCards(previous, current)) {
      return {
        isValid: false,
        selectedCards,
        invalidCardId: current.id,
        reason: "2枚目以降は直前のカードと同じ数字または同じ記号のみ提出できます。",
      };
    }
  }

  return { isValid: true, selectedCards };
}

function calculateCombinedEffects(cards: UnoCard[]): { skipCount: number; reverseCount: number; drawCount: number } {
  return cards.reduce(
    (acc, card) => {
      if (card.type === "skip") acc.skipCount += 1;
      if (card.type === "reverse") acc.reverseCount += 1;
      if (card.type === "draw2") acc.drawCount += 2;
      return acc;
    },
    { skipCount: 0, reverseCount: 0, drawCount: 0 },
  );
}

function waitMs(ms: number): Promise<void> {
  return new Promise((resolve) => {
    window.setTimeout(resolve, ms);
  });
}

function wrapTurnIndex(index: number, totalPlayers: number): number {
  if (totalPlayers <= 0) return 0;
  const mod = index % totalPlayers;
  return mod >= 0 ? mod : mod + totalPlayers;
}

