const CASINO_BET_STEP = 10;
const ROOM_SERVER_QUERY_PARAM_KEY = "roomServer";
const ROOM_CODE_QUERY_PARAM_KEY = "roomCode";
const ROOM_INVITE_TOKEN_QUERY_PARAM_KEY = "inviteToken";
